/**
 * CopilotKit Adapter for Unify
 *
 * <RequestExample>
 * ```jsx CopilotRuntime Example
 * const copilotKit = new CopilotRuntime();
 * return copilotKit.response(req, new UnifyAdapter());
 * ```
 * </RequestExample>
 *
 * You can easily set the model to use by passing it to the constructor.
 * ```jsx
 * const copilotKit = new CopilotRuntime();
 * return copilotKit.response(
 *   req,
 *   new UnifyAdapter({ model: "llama-3-8b-chat@fireworks-ai" }),
 * );
 * ```
 */
import type {
  CopilotRuntimeChatCompletionRequest,
  CopilotRuntimeChatCompletionResponse,
  CopilotServiceAdapter,
} from "../service-adapter";
import { randomId, randomUUID } from "@copilotkit/shared";
import { createOpenAI } from "@ai-sdk/openai";
import type { LanguageModel } from "ai";
import {
  convertActionInputToOpenAITool,
  convertMessageToOpenAIMessage,
} from "../openai/utils";

export interface UnifyAdapterParams {
  apiKey?: string;
  model: string;
}

export class UnifyAdapter implements CopilotServiceAdapter {
  private apiKey?: string;
  public model: string;
  private start: boolean;
  public provider = "unify";

  public get name() {
    return "UnifyAdapter";
  }

  constructor(options?: UnifyAdapterParams) {
    // Was `this.apiKey = "UNIFY_API_KEY"` — the *name* of the variable, stored
    // as the key. Every request that relied on the default authenticated with
    // the literal placeholder and came back 401. Read the variable instead,
    // matching how the Google adapter falls back to GOOGLE_API_KEY.
    this.apiKey = options?.apiKey ?? process.env.UNIFY_API_KEY;
    this.model = options?.model;
    this.start = true;
  }

  async process(
    request: CopilotRuntimeChatCompletionRequest,
  ): Promise<CopilotRuntimeChatCompletionResponse> {
    const tools = request.actions.map(convertActionInputToOpenAITool);
    // Lazy require for optional peer dependency
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const OpenAI = require("openai").default;
    const openai = new OpenAI({
      apiKey: this.apiKey,
      baseURL: "https://api.unify.ai/v0/",
    });
    const forwardedParameters = request.forwardedParameters;

    const messages = request.messages.map((m) =>
      convertMessageToOpenAIMessage(m),
    );

    const stream = await openai.chat.completions.create({
      model: this.model,
      messages: messages,
      stream: true,
      ...(tools.length > 0 && { tools }),
      ...(forwardedParameters?.temperature && {
        temperature: forwardedParameters.temperature,
      }),
    });

    let model = null;
    let currentMessageId: string;
    let currentToolCallId: string;
    request.eventSource.stream(async (eventStream$) => {
      let mode: "function" | "message" | null = null;
      for await (const chunk of stream) {
        if (this.start) {
          model = chunk.model;
          currentMessageId = randomId();
          eventStream$.sendTextMessageStart({ messageId: currentMessageId });
          eventStream$.sendTextMessageContent({
            messageId: currentMessageId,
            content: `Model used: ${model}\n`,
          });
          eventStream$.sendTextMessageEnd({ messageId: currentMessageId });
          this.start = false;
        }
        const toolCall = chunk.choices[0].delta.tool_calls?.[0];
        const content = chunk.choices[0].delta.content;

        // When switching from message to function or vice versa,
        // send the respective end event.
        // If toolCall?.id is defined, it means a new tool call starts.
        if (mode === "message" && toolCall?.id) {
          mode = null;
          eventStream$.sendTextMessageEnd({ messageId: currentMessageId });
        } else if (
          mode === "function" &&
          (toolCall === undefined || toolCall?.id)
        ) {
          mode = null;
          eventStream$.sendActionExecutionEnd({
            actionExecutionId: currentToolCallId,
          });
        }

        // If we send a new message type, send the appropriate start event.
        if (mode === null) {
          if (toolCall?.id) {
            mode = "function";
            currentToolCallId = toolCall!.id;
            eventStream$.sendActionExecutionStart({
              actionExecutionId: currentToolCallId,
              actionName: toolCall!.function!.name,
            });
          } else if (content) {
            mode = "message";
            currentMessageId = chunk.id;
            eventStream$.sendTextMessageStart({ messageId: currentMessageId });
          }
        }

        // send the content events
        if (mode === "message" && content) {
          eventStream$.sendTextMessageContent({
            messageId: currentMessageId,
            content: content,
          });
        } else if (mode === "function" && toolCall?.function?.arguments) {
          eventStream$.sendActionExecutionArgs({
            actionExecutionId: currentToolCallId,
            args: toolCall.function.arguments,
          });
        }
      }

      // send the end events
      if (mode === "message") {
        eventStream$.sendTextMessageEnd({ messageId: currentMessageId });
      } else if (mode === "function") {
        eventStream$.sendActionExecutionEnd({
          actionExecutionId: currentToolCallId,
        });
      }

      eventStream$.complete();
    });

    return {
      threadId: request.threadId || randomUUID(),
    };
  }

  /**
   * Unify's API is OpenAI-compatible, so the model is built from the OpenAI
   * provider pointed at Unify's base URL with this adapter's own key. Without
   * it the runtime rebuilds a bare "unify/<model>" string, which is not a
   * provider it can resolve.
   */
  getLanguageModel(): LanguageModel {
    const provider = createOpenAI({
      baseURL: "https://api.unify.ai/v0/",
      apiKey: this.apiKey,
    });
    return provider(this.model);
  }
}
